int irda_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int flags) {
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    int copied = 0;
    int err = 0;

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb) {
        return -EAGAIN;
    }

    if (size > skb->len) {
        size = skb->len;
    }

    copied = skb_copy_datagram_msg(skb, 0, msg, size);
    if (copied < 0) {
        err = copied;
        goto out;
    }

    if (copied < skb->len) {
        msg->msg_flags |= MSG_TRUNC;
    }

    if (sk->sk_stop_flow && skb_queue_len(&sk->sk_receive_queue) < IRDA_RECV_QUEUE_HIGH_WATER) {
        sk->sk_stop_flow = 0;
    }

    out:
    kfree_skb(skb);
    return (err < 0) ? err : copied;
}
